type Priority="Nichts"|"Dringend"|"Wenn's passt"|"Angebot";
type Item={id:string;name:string;cat:string;icon:string;qty:string;note?:string;priority?:Priority|"Normal"|Priority[];favorite?:boolean;source?:"recipe"|"offer"|"search";repeatStep?:string;priceEstimate?:number;offer?:{id:string;store:string;storeName:string;price:number;oldPrice:number|null;unit:string;url:string|null;validUntil?:string|null}};
type ProductSearchResult={id:string;name:string;unit:string;image:string|null;prices:{store:string;price:number}[];bestPrice:number;bestStore:string;comparePrice:number|null;compareUnit:string|null};
type ShoppingCard={id:string;store:string;code?:string;type?:"code"|"image";note?:string;imageId?:string;imageName?:string};
type QuantityUnit="Stück"|"Liter"|"Gramm"|"Kilogramm"|string;
const quantityUnits:QuantityUnit[]=["Stück","Liter","Gramm","Kilogramm"];
const priorities=[{label:"Dringend",Icon:Zap},{label:"Angebot",Icon:Tag},{label:"Wenn's passt",Icon:Clock3},{label:"Nichts",Icon:Minus}] as const;
function priorityValues(value:Item["priority"]):Priority[]{const raw=Array.isArray(value)?value:value?[value]:["Nichts"];const values=[...new Set(raw.map(item=>item==="Normal"?"Nichts":item).filter((item):item is Priority=>priorities.some(option=>option.label===item)))];if(values.includes("Nichts")||!values.length)return["Nichts"];return priorities.map(option=>option.label).filter(label=>values.includes(label))}
function togglePriority(value:Item["priority"],label:Priority):Priority[]{const current=priorityValues(value);if(label==="Nichts")return["Nichts"];const selected=current.includes(label)?current.filter(item=>item!==label):[...current.filter(item=>item!=="Nichts"),label];return selected.length?priorityValues(selected):["Nichts"]}
function parseQuantity(value:string){const match=value.trim().match(/^(\d+(?:[.,]\d+)?)\s*(.*?)\s*$/);if(!match)return{amount:1,unit:"Stück" as QuantityUnit};const unitKey=match[2].toLocaleLowerCase("de");const unit:QuantityUnit=unitKey==="l"||unitKey==="liter"||unitKey==="litre"?"Liter":unitKey==="g"||unitKey==="gramm"||unitKey==="gram"?"Gramm":unitKey==="kg"||unitKey==="kilogramm"||unitKey==="kilogram"?"Kilogramm":unitKey==="x"||unitKey==="stk"||unitKey==="stk."||unitKey==="stück"||unitKey==="stueck"||!unitKey?"Stück":match[2].trim();return{amount:Number(match[1].replace(",","."))||1,unit}}
function formatQuantity(amount:number|string,unit:QuantityUnit){const parsed=Number(String(amount).replace(",","."));const minimum=unit==="Stück"?1:.01;return `${Math.max(minimum,Number.isFinite(parsed)?parsed:minimum)} ${unit}`}
function createItemId(){try{const id=globalThis.crypto?.randomUUID?.();if(id)return id}catch{}return `item-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,10)}`}
function formatQuantityStep(value:number,unit:string){const digits=unit==="Stück"?0:3;return `${new Intl.NumberFormat("de-AT",{maximumFractionDigits:digits}).format(Math.max(unit==="Stück"?1:.01,value))} ${unit}`}
function quantityInUnit(value:string,targetUnit:string){const parsed=parseQuantity(value);if(parsed.unit===targetUnit)return parsed.amount;if(parsed.unit==="Kilogramm"&&targetUnit==="Gramm")return parsed.amount*1000;if(parsed.unit==="Gramm"&&targetUnit==="Kilogramm")return parsed.amount/1000;return null}
function incrementQuantity(value:string,step="1 Stück"){const current=parseQuantity(value);const increment=quantityInUnit(step,current.unit);return formatQuantityStep(current.amount+(increment??(current.unit==="Stück"?1:.1)),current.unit)}
