function suggestEmoji(name:string,category:string){const normalized=name.trim().toLocaleLowerCase("de");const known=matchProductIcon(name);if(known)return known.emoji;const match=emojiHints.find(([terms])=>terms.some(term=>normalized.includes(term)));if(match)return match[1];if(category.includes("Gemüse"))return"🥬";if(category.includes("Milch"))return"🥛";if(category.includes("Backwaren"))return"🍞";if(category.includes("Getränke"))return"🥤";if(category.includes("Fleisch"))return"🍗";if(category.includes("Nudeln"))return"🍝";if(category.includes("Haushalt"))return"🧴";return"🛍️"}
const emojiSearchAliases:[string,string][]=[["tomate","tomato"],["äpfel","apple"],["apfel","apple"],["banane","banana"],["milch","milk"],["ei","egg"],["eier","egg"],["brot","bread"],["semmel","bread"],["käse","cheese"],["gurke","cucumber"],["paprika","pepper"],["nudel","pasta"],["reis","rice"],["kaffee","coffee"],["wasser","water"],["saft","juice"],["papier","toilet paper"],["spülmittel","soap"],["waschmittel","soap"],["huhn","chicken"],["hähnchen","chicken"],["fleisch","meat"],["fisch","fish"],["chips","chips"],["zahn","toothbrush"],["blume","flower"]];
function emojiSearchTerm(name:string,category:string){const normalized=name.trim().toLocaleLowerCase("de");const match=emojiSearchAliases.find(([term])=>normalized.includes(term));if(match)return match[1];if(normalized.length>=2)return normalized;return category.includes("Gemüse")?"vegetable":category.includes("Milch")?"milk":category.includes("Backwaren")?"bread":category.includes("Getränke")?"drink":category.includes("Fleisch")?"meat":category.includes("Nudeln")?"pasta":category.includes("Haushalt")?"cleaning":"food"}
type EmojiMatch={name:string;emoji:string;code:string};
function ProductIcon({value,className=""}:{value:string;className?:string}){return value.startsWith("data:image/")||value.startsWith("/api/emoji/image?")||/^https?:\/\//i.test(value)?<img className={`uploaded-product-image ${className}`} src={value} alt="" loading="lazy"/>:<>{value}</>}
function PriorityBadge({priority,iconOnly=false}:{priority:Priority;iconOnly?:boolean}){const entry=priorities.find(option=>option.label===priority)!;const Icon=entry.Icon;return <span className={`tile-priority priority-${entry.label.toLocaleLowerCase().replace(/[^a-z]+/g,"-")}${iconOnly?" priority-icon-only":""}`} title={entry.label} aria-label={entry.label}><Icon size={11}/>{!iconOnly&&<span>{entry.label}</span>}</span>}
function PriorityBadges({priority,position="corner",iconOnly=false}:{priority:Item["priority"];position?:"corner"|"catalog"|"preview";iconOnly?:boolean}){const values=priorityValues(priority).filter(value=>value!=="Nichts");if(!values.length)return null;return <span className={`tile-priority-stack priority-${position}`}>{values.map(value=><PriorityBadge priority={value} iconOnly={iconOnly} key={value}/>)}</span>}
