 const [emojiMatches,setEmojiMatches]=useState<EmojiMatch[]>([]);const [emojiSearching,setEmojiSearching]=useState(false);const [emojiDownloading,setEmojiDownloading]=useState("");const emojiRequest=useRef<AbortController|null>(null);
  const [iconPickerOpen,setIconPickerOpen]=useState(false);const [iconQuery,setIconQuery]=useState("");const [iconCategory,setIconCategory]=useState("Alle");
