 useEffect(()=>{const url=new URL(window.location.href);if(url.searchParams.get("entdecken")==="1"){setDiscoverMounted(true);setDiscoverOpen(true)}const onPopState=()=>{const next=new URL(window.location.href);const open=next.searchParams.get("entdecken")==="1";setDiscoverOpen(open);if(open)setDiscoverMounted(true)};const onShoppingHome=()=>{collapseSearch();setDiscoverOpen(false);const next=new URL(window.location.href);if(next.searchParams.has("entdecken")){next.searchParams.delete("entdecken");window.history.replaceState(window.history.state,"",`${next.pathname}${next.search}${next.hash}`)}};window.addEventListener("popstate",onPopState);window.addEventListener("wg-shopping-home",onShoppingHome);return()=>{window.removeEventListener("popstate",onPopState);window.removeEventListener("wg-shopping-home",onShoppingHome)}},[]);
