 const cheapestMarketProduct=useMemo(()=>{if(!sortedMarketResults.length)return null;const units=sortedMarketResults.map(product=>product.compareUnit).filter((unit):unit is string=>Boolean(unit));const preferredUnit=units.sort((a,b)=>units.filter(unit=>unit===b).length-units.filter(unit=>unit===a).length)[0]??null;const comparable=preferredUnit?sortedMarketResults.filter(product=>product.compareUnit===preferredUnit&&product.comparePrice!==null):[];return(comparable.length?comparable.reduce((best,current)=>current.comparePrice!<best.comparePrice!?current:best):sortedMarketResults.reduce((best,current)=>current.bestPrice<best.bestPrice?current:best)).id},[sortedMarketResults]);
