 function mobileEditPress(onEdit:()=>void){return{
  onPointerDown:(event:ReactPointerEvent<HTMLButtonElement>)=>{if(event.pointerType==="mouse"&&event.button!==0)return;longPressTriggered.current=false;longPressOrigin.current={x:event.clientX,y:event.clientY};if(longPressTimer.current)clearTimeout(longPressTimer.current);longPressTimer.current=setTimeout(()=>{longPressTimer.current=null;longPressTriggered.current=true;onEdit()},500)},
  onPointerMove:(event:ReactPointerEvent<HTMLButtonElement>)=>{if(!longPressTimer.current)return;if(Math.abs(event.clientX-longPressOrigin.current.x)>12||Math.abs(event.clientY-longPressOrigin.current.y)>12){clearTimeout(longPressTimer.current);longPressTimer.current=null}},
  onPointerUp:()=>{if(longPressTimer.current){clearTimeout(longPressTimer.current);longPressTimer.current=null}if(longPressTriggered.current)setTimeout(()=>{longPressTriggered.current=false},450)},
  onPointerCancel:()=>{if(longPressTimer.current){clearTimeout(longPressTimer.current);longPressTimer.current=null}longPressTriggered.current=false},
  onContextMenu:(event:ReactMouseEvent<HTMLButtonElement>)=>{event.preventDefault()},
  onClickCapture:(event:ReactMouseEvent<HTMLButtonElement>)=>{if(longPressTriggered.current){event.preventDefault();event.stopPropagation();longPressTriggered.current=false}}
 }}

