 async function downloadEmoji(match:EmojiMatch){setEmojiDownloading(match.code);try{const response=await fetch(`/api/emoji/image?code=${encodeURIComponent(match.code)}`);if(!response.ok)throw new Error("Symbol nicht verfügbar");const bytes=new Uint8Array(await response.arrayBuffer());let binary="";for(const byte of bytes)binary+=String.fromCharCode(byte);const icon=`data:image/svg+xml;base64,${btoa(binary)}`;setEditor(current=>current?{...current,icon}:current);setMessage(`${match.name} als Produktsymbol übernommen.`)}catch{setEditor(current=>current?{...current,icon:match.emoji}:current);setMessage("Symbol als Emoji übernommen.")}finally{setEmojiDownloading("")}}
  const localSuggestion=useMemo(()=>{if(!editor)return null;const term=(iconQuery||editor.name).trim().toLocaleLowerCase("de");const terms=term.split(/\s+/).filter(value=>value.length>1);return [...productIcons].map(icon=>({icon,score:(terms.some(value=>icon.name.toLocaleLowerCase("de").includes(value))?4:0)+(icon.category===editor.cat?2:0)})).filter(entry=>entry.score>0).sort((a,b)=>b.score-a.score)[0]?.icon||null},[editor?.name,editor?.cat,iconQuery]);
