  const parsedQuantity=parseQuantity(editor.qty);
  if(!Number.isFinite(parsedQuantity.amount)||parsedQuantity.amount<=0){setMessage("Die Menge muss größer als 0 sein.");return;}
  const category=editor.cat==="Eigene Kategorie"?(customCategory.trim()||"Sonstiges"):editor.cat;
