  function addSearchItem(){const name=search.trim();if(!name){beginNew();return}haptic();const existing=items.find(item=>item.name.toLocaleLowerCase()===name.toLocaleLowerCase());if(existing){const updated={...existing,qty:incrementQuantity(existing.qty,existing.repeatStep||"1 Stück")};setItems(items.map(item=>item.id===existing.id?updated:item));setMessage(`${existing.name}: Menge jetzt ${updated.qty}.`);collapseSearch();return}const category=filter==="Alle"?"Sonstiges":filter;const saved:Item={id:createItemId(),name,cat:category,icon:suggestEmoji(name,category),qty:"1 Stück",priority:["Nichts"]};setItems([saved,...items]);setCatalogItems(current=>current.some(item=>item.name.toLocaleLowerCase()===name.toLocaleLowerCase())?current:[{...saved,id:`catalog-${saved.id}`},...current]);setMessage(`${name} hinzugefügt.`);collapseSearch()}
 function addMarketSearchProduct(product:ProductSearchResult){const name=product.name.trim();if(!name)return;haptic();const icon=product.image||matchProductIcon(name)?.emoji||suggestEmoji(name,"Sonstiges");setItems(current=>{const existing=current.find(item=>item.name.trim().toLocaleLowerCase("de")===name.toLocaleLowerCase("de"));if(existing){const qty=incrementQuantity(existing.qty,existing.repeatStep||"1 Stück");const parsed=parseQuantity(qty);const priceEstimate=parsed.unit==="Stück"?Math.round(parsed.amount*product.bestPrice*100)/100:(existing.priceEstimate??0)+product.bestPrice;return current.map(item=>item.id===existing.id?{...item,icon,qty,priceEstimate}:item)}return[{id:createItemId(),name,cat:"Sonstiges",icon,qty:"1 Stück",note:"",priority:["Nichts"],source:"search",repeatStep:"1 Stück",priceEstimate:product.bestPrice},...current]})}
 function saveFeatureItem(item:Item){const name=item.name.trim().toLocaleLowerCase("de");if(catalogItems.some(product=>product.name.trim().toLocaleLowerCase("de")===name)){setMessage(`${item.name} ist bereits gespeichert.`);return}const{source,offer,...product}=item;const saved={...product,id:`catalog-${createItemId()}`,repeatStep:item.qty||"1 Stück"};setCatalogItems(current=>current.some(value=>value.name.trim().toLocaleLowerCase("de")===name)?current:[saved,...current]);setItems(current=>current.map(value=>value.id===item.id?{...value,source:undefined,offer:undefined,repeatStep:saved.repeatStep}:value));setMessage(`${item.name} als Produkt gespeichert.`)}
 function uploadProductImage(file?:File){if(!file)return;if(!file.type.startsWith("image/")){setMessage("Bitte eine Bilddatei auswählen.");return}if(file.size>5*1024*1024){setMessage("Das Bild darf höchstens 5 MB groß sein.");return}const url=URL.createObjectURL(file);const image=new Image();image.onload=()=>{const canvas=document.createElement("canvas");canvas.width=128;canvas.height=128;const context=canvas.getContext("2d");if(!context){URL.revokeObjectURL(url);setMessage("Das Bild konnte nicht verarbeitet werden.");return}const scale=Math.min(128/image.width,128/image.height);const width=image.width*scale;const height=image.height*scale;context.clearRect(0,0,128,128);context.drawImage(image,(128-width)/2,(128-height)/2,width,height);const data=canvas.toDataURL("image/webp",0.76);URL.revokeObjectURL(url);setEditor(current=>current?{...current,icon:data}:current)};image.onerror=()=>{URL.revokeObjectURL(url);setMessage("Das Bild konnte nicht geladen werden.")};image.src=url}
  function editListItem(item:Item){collapseSearch();const catalogItem=catalogItems.find(candidate=>candidate.name.toLocaleLowerCase()===item.name.toLocaleLowerCase());setEditor({...(catalogItem||item),id:item.id,qty:item.qty,favorite:favoriteNames.some(name=>name.toLocaleLowerCase()===item.name.toLocaleLowerCase())});setIsNew(false);setCatalogEdit(false);setTemporaryEdit({targetId:item.id,originalName:item.name});setCustomCategory(categories.includes(item.cat)?"":item.cat)}
  function editCatalog(item:Item){collapseSearch();setCatalogEdit(true);setTemporaryEdit(null);setIsNew(false);setEditor({...item,favorite:favoriteNames.some(name=>name.toLocaleLowerCase()===item.name.toLocaleLowerCase())});setCustomCategory(categories.includes(item.cat)?"":item.cat)}
